// Build supabase/neop_exam_questions_seed.sql from scripts/neop-exam-bank.mjs.
//
// Run: node scripts/gen-neop-exam.mjs
//
// The generated file UPSERTS ON `code` and retires by setting active = false.
// It never deletes and never truncates, which is the one thing the AEMT bank's
// three files get wrong and warn about at length: exam_attempts.question_ids
// holds bare ids with no foreign key, so a re-seed that recreates rows silently
// orphans every attempt already on record. Here a re-run corrects the wording
// of an item in place, and an item dropped from the bank stops being drawn
// while the attempts that served it still resolve.
import { writeFileSync, readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { CLINICAL, OPERATIONS, FIT } from './neop-exam-bank.mjs'

const __dirname = dirname(fileURLToPath(import.meta.url))
export const SEED_PATH = join(__dirname, '..', 'supabase', 'neop_exam_questions_seed.sql')

const q = (s) => `'${String(s).replace(/'/g, "''")}'`
const arr = (xs) => `array[${xs.map(q).join(',')}]`

/** Every item, in one list, with its section and display domain resolved. */
export function items() {
  return [
    ...CLINICAL.map((i) => ({ ...i, section: 'clinical', domain: i.domain })),
    ...OPERATIONS.map((i) => ({ ...i, section: 'operations', domain: 'Our operation' })),
    ...FIT.map((i) => ({ ...i, section: 'fit', domain: 'What you want' })),
  ]
}

export function buildSeedSql() {
  const all = items()
  const rows = all
    .map(
      (i) =>
        `(${q(i.section)}, ${q(i.code)}, ${q(i.domain)}, ${q(i.stem)}, ${arr(i.options)}, ${
          i.answer === null || i.answer === undefined ? 'null' : i.answer
        })`,
    )
    .join(',\n')

  const counts = ['clinical', 'operations', 'fit']
    .map((s) => `${all.filter((i) => i.section === s).length} ${s}`)
    .join(', ')

  return `-- ---------------------------------------------------------------------------
-- NEOP selection exam question bank (${all.length} items: ${counts}).
--
-- GENERATED by scripts/gen-neop-exam.mjs from scripts/neop-exam-bank.mjs.
-- Do not hand-edit: edit the bank and run \`npm run check:neop\`, which
-- regenerates nothing but tells you this file has drifted.
--
-- Requires the 2026-08-18-neop-selection-exam.sql migration (or a schema.sql
-- new enough to contain the program/section/code columns).
--
-- SAFE TO RE-RUN, and safe to re-run against a live exam. It upserts on
-- \`code\` and never deletes: an id already recorded in
-- exam_attempts.question_ids keeps its row and its meaning. Items removed from
-- the bank are retired (active = false) rather than dropped, so a historical
-- attempt still resolves to the question it actually asked.
--
-- The AEMT bank is untouched — every statement here is fenced to
-- program = 'neop'.
--
-- The preference items carry answer = null on purpose. That is what makes them
-- unscored: the database generates \`scored\` from it and exam_submit skips
-- them. Giving one of them a key would score a candidate on what they want.
-- ---------------------------------------------------------------------------

insert into public.exam_questions (program, section, code, domain, stem, options, answer, active)
select 'neop', v.section, v.code, v.domain, v.stem, v.options, v.answer, true
from (values
${rows}
) as v(section, code, domain, stem, options, answer)
on conflict (code) where code is not null do update
  set section = excluded.section,
      domain  = excluded.domain,
      stem    = excluded.stem,
      options = excluded.options,
      answer  = excluded.answer,
      active  = true;

-- Retire anything no longer in the bank. Never deleted — see the header.
update public.exam_questions
   set active = false
 where program = 'neop'
   and active
   and code not in (${all.map((i) => q(i.code)).join(', ')});

-- Confirm the draw can be filled: 12 clinical, 16 operations, and at least one
-- preference item are needed before a candidate can start.
select section, count(*) filter (where active) as active_items, count(*) as total_items
  from public.exam_questions
 where program = 'neop'
 group by section
 order by section;
`
}

const invokedDirectly = process.argv[1] && process.argv[1].endsWith('gen-neop-exam.mjs')
if (invokedDirectly) {
  const sql = buildSeedSql()
  let before = ''
  try {
    before = readFileSync(SEED_PATH, 'utf8')
  } catch {
    /* first run */
  }
  writeFileSync(SEED_PATH, sql)
  console.log(
    `${before === sql ? 'unchanged' : 'wrote'}  supabase/neop_exam_questions_seed.sql  (${
      items().length
    } items)`,
  )
}
